-- 048: independent Arkanis sheets and ingredient library. Apply after 047.
begin;

insert into public.rpg_systems(id,name,slug,version,description,active)
values('00000000-0000-4000-8000-000000000002','Arkanis','arkanis','Livro de Regras · 2026','Sistema sem classes: Corpo, Mente, Espírito, aptidões, maestrias, grimórios e alquimia.',true)
on conflict(slug) do update set name=excluded.name,version=excluded.version,description=excluded.description,active=true;

create table if not exists public.arkanis_ingredients (
 id text primary key,name text not null,number integer not null unique,
 habitat_id text not null,habitat text not null,affinities text not null,icon text not null,
 tags text[] not null default array['ingredientes']
);
alter table public.arkanis_ingredients enable row level security;
revoke all on public.arkanis_ingredients from public,anon,authenticated;
grant select on public.arkanis_ingredients to authenticated;
drop policy if exists arkanis_ingredients_read on public.arkanis_ingredients;
create policy arkanis_ingredients_read on public.arkanis_ingredients for select to authenticated using(true);
insert into public.arkanis_ingredients(id,name,number,habitat_id,habitat,affinities,icon,tags)
select id,name,number,habitat_id,habitat,affinities,icon,array['ingredientes']
