me":"Flor do Eclipse Negro","habitat_id":"amaldicoadas","habitat":"Terras amaldiçoadas e corrompidas","affinities":"maldições e enfraquecimento da luz.","tags":["ingredientes"],"icon":"/icons/arkanis/ingredients/arkanis-171.svg","form":"flower"},{"id":"arkanis-172","number":172,"name":"Espinho de Sangue Sombrio","habitat_id":"amaldicoadas","habitat":"Terras amaldiçoadas e corrompidas","affinities":"transferência de vitalidade.","tags":["ingredientes"],"icon":"/icons/arkanis/ingredients/arkanis-172.svg","form":"claw"},{"id":"arkanis-173","number":173,"name":"Cinza de Alma Perdida","habitat_id":"amaldicoadas","habitat":"Terras amaldiçoadas e corrompidas","affinities":"enfraquecimento espiritual.","tags":["ingredientes"],"icon":"/icons/arkanis/ingredients/arkanis-173.svg","form":"powder"},{"id":"arkanis-174","number":174,"name":"Cogumelo da Loucura","habitat_id":"amaldicoadas","habitat":"Terras amaldiçoadas e corrompidas","affinities":"confusão e alucinações.","tags":["ingredientes"],"icon":"/icons/arkanis/ingredients/arkanis-174.svg","form":"mushroom"},{"id":"arkanis-175","number":175,"name":"Raiz de Árvore Maldita","habitat_id":"amaldicoadas","habitat":"Terras amaldiçoadas e corrompidas","affinities":"aprisionamento e vínculos.","tags":["ingredientes"],"icon":"/icons/arkanis/ingredients/arkanis-175.svg","form":"root"},{"id":"arkanis-176","number":176,"name":"Cristal de Corrupção","habitat_id":"amaldicoadas","habitat":"Terras amaldiçoadas e corrompidas","affinities":"deterioração de encantamentos.","tags":["ingredientes"],"icon":"/icons/arkanis/ingredients/arkanis-176.svg","form":"crystal"},{"id":"arkanis-177","number":177,"name":"Lágrima de Demônio Menor","habitat_id":"amaldicoadas","habitat":"Terras amaldiçoadas e corrompidas","affinities":"magia sombria e pactos.","tags":["ingredientes"],"icon":"/icons/arkanis/ingredients/arkanis-177.svg","form":"drop"},{"id":"arkanis-178","number":178,"name":"Sangue de Espinho-Vivo","habitat_id":"amaldicoadas","habitat":"Terras am