 as x(id text,name text,number integer,habitat_id text,habitat text,affinities text,icon text)
on conflict(id) do update set name=excluded.name,habitat_id=excluded.habitat_id,habitat=excluded.habitat,affinities=excluded.affinities,icon=excluded.icon,tags=excluded.tags;

create or replace function private.arkanis48_validate(s jsonb) returns void language plpgsql set search_path='' as $$
declare k text;v integer;score integer;a integer;modifier integer;total integer;maximum integer;entry jsonb;ord jsonb;
begin
 if jsonb_typeof(s)<>'object' or s->>'system' is distinct from 'arkanis' or s->>'schema_version' is distinct from '1' or pg_column_size(s)>262144 then raise exception 'Ficha de Arkanis inválida ou muito extensa.';end if;
 if s->>'race_id' not in('human','elf','dwarf','orc','triton','harpy','demon') or s->>'race_id' is null then raise exception 'Escolha uma raça de Arkanis.';end if;
 if coalesce((s->>'level')::integer,0) not between 1 and 100 or coalesce((s->>'hp_max')::integer,0)<1 then raise exception 'Confira o nível e os HP máximos definidos com o mestre.';end if;
 if jsonb_typeof(s->'attributes') is distinct from 'object' or jsonb_typeof(s->'attribute_adjustments') is distinct from 'object' or jsonb_typeof(s->'arkano') is distinct from 'object' or jsonb_typeof(s->'aptitudes') is distinct from 'object' then raise exception 'Atributos, Arkano ou aptidões inválidos.';end if;
 foreach k in array array['body','mind','spirit'] loop
  if jsonb_typeof(s->'arkano'->k) is distinct from 'number' or (s->'arkano'->>k)::numeric<>trunc((s->'arkano'->>k)::numeric) or (s->'arkano'->>k)::integer not between 1 and 10 then raise exception 'Corpo, Mente e Espírito vão de 1 a 10.';end if;
 end loop;
 total=(s->'arkano'->>'body')::integer+(s->'arkano'->>'mind')::integer+(s->'arkano'->>'spirit')::integer+coalesce((s->'arkano'->>'bonus')::integer,0)+case when s->>'race_id'='elf' then 7 else 0 end;
 if total not between 1 and 100 then raise exception 'O Arkano total deve estar entre 1 e 100.';end if;
 modifier=case when total<=20 then 0 when total<=30 then 1 when total<=50 then 2 when total<=70 then 3 when total<75 then 4 when total=75 then null when total<=80 then 5 when total<=85 then 6 when total<=90 then 7 when total<=95 then 8 when total<=99 then 9 else 10 end;
 modifier=coalesce((s->'arkano'->>'modifier_override')::integer,modifier);
 if modifier is null or modifier not between 0 and 10 then raise exception 'Confira o modificador de Arkano; o valor 75 exige decisão do mestre.';end if;
 if s->>'human_attribute' is null or s->>'human_attribute' not in('for','agi','res','int','sen','pre') then raise exception 'Confira o atributo humano à escolha.';end if;
 foreach k in array array['for','agi','res','int','sen','pre'] loop
  if jsonb_typeof(s->'attributes'->k) is distinct from 'number' or (s->'attributes'->>k)::numeric<>trunc((s->'attributes'->>k)::numeric) or jsonb_typeof(s->'attribute_adjustments'->k) is distinct from 'number' or (s->'attribute_adjustments'->>k)::numeric<>trunc((s->'attribute_adjustments'->>k)::numeric) then raise exception 'Os atributos e ajustes devem ser inteiros.';end if;
  a=case s->>'race_id' when 'human' then case when k='int' then 1 else 0 end+case when k=s->>'human_attribute' then 1 else 0 end when 'elf' then case when k in('agi','int') then 1 else 0 end when 'dwarf' then case k when 'res' then 2 when 'for' then 1 else 0 end when 'orc' then case k when 'for' then 2 when 'pre' then 1 else 0 end when 'triton' then case k when 'res' then 1 when 'sen' then 2 else 0 end when 'harpy' then case k when 'agi' then 2 when 'sen' then 1 else 0 end when 'demon' then case k when 'res' then 1 when 'pre' then 2 else 0 end end;
  a=a+case when k='res' and (s->'arkano'->>'body')::integer=10 or k='int' and (s->'arkano'->>'mind')::integer=10 or k='pre' and (s->'arkano'->>'spirit')::integer=10 then 1 else 0 end;
  score=(s->'attributes'->>k)::integer+(s->'attribute_adjustments'->>k)::integer+a;
  if score not between 1 and 30 then raise exception 'Os atributos finais devem estar entre 1 e 30.';end if;
  if k='int' then maximum=((s->>'level')::integer*5+score)*greatest(1,modifier);end if;
 end loop;
 maximum=coalesce((s->>'mana_max_override')::integer,maximum);
 if maximum<0 or coalesce((s->>'mana_current')::integer,-1) not between 0 and maximum or coalesce((s->>'hp_current')::integer,-1) not between 0 and (s->>'hp_max')::integer or coalesce((s->>'sanity_max')::integer,0)<1 or coalesce((s->>'sanity_current')::integer,-1) not between 0 and (s->>'sanity_max')::integer then raise exception 'Confira os valores atuais e máximos de HP, Mana e Sanidade.';end if;
 foreach k in array array['hp_current','hp_max','mana_current','sanity_current','sanity_max','level','xp'] loop
  if jsonb_typeof(s->k) is distinct from 'number' or (s->>k)::numeric<>trunc((s->>k)::numeric) or (s->>k)::numeric<0 then raise exception 'Recursos e nível devem ser inteiros e não negativos.';end if;
 end loop;
 for entry in select value from jsonb_each(s->'aptitudes') loop
  if jsonb_typeof(entry) is distinct from 'number' or entry::numeric<>trunc(entry::numeric) or entry::integer not between 0 and 3 then raise exception 'As aptidões vão de 0 a 3.';end if;
 end loop;
 if jsonb_typeof(s->'armor') is distinct from 'object' or coalesce((s->'armor'->>'value')::integer,-1)<0 or coalesce((s->'armor'->>'durability_max')::integer,-1)<0 or coalesce((s->'armor'->>'durability_current')::integer,-1) not between 0 and (s->'armor'->>'durability_max')::integer then raise exception 'Confira VA e durabilidade da armadura.';end if;
 foreach k in array array['weapons','grimoire','techniques'] loop
  if jsonb_typeof(s->k) is distinct from 'array' or jsonb_array_length(s->k)>300 then raise exception 'Confira as listas da ficha (até 300 registros por seção).';end if;
  for entry in select value from jsonb_array_elements(s->k) loop
   if coalesce(length(trim(entry->>'name')),0) not between 1 and 120 or entry->>'id' is null then raise exception 'Todo registro precisa de nome e identificador.';end if;
   perform (entry->>'id')::uuid;
   if k='weapons' then
    if coalesce((entry->>'die')::integer,0) not in(4,6,8,10,12,20) or coalesce((entry->>'mastery')::integer,0) not between 1 and 5 or (entry->>'mastery')::integer=3 and coalesce((entry->>'dice_at_third')::integer,0) not in(3,4) then raise exception 'Confira o dado e a maestria da arma.';end if;
   else
    if coalesce((entry->>'learning_level')::integer,-1)<0 then raise exception 'O NA deve ser positivo ou zero.';end if;
    if k='grimoire' then
     if entry->>'highest_order' is null or entry->>'highest_order' not in('primaria','desperta','elevada','arcana','suprema','divina') or jsonb_typeof(entry->'orders') is distinct from 'object' then raise exception 'Confira as ordens do grimório.';end if;
     for ord in select value from jsonb_each(entry->'orders') loop
      if jsonb_typeof(ord->'mana') is distinct from 'number' or (ord->>'mana')::numeric<0 or (ord->>'mana')::numeric<>trunc((ord->>'mana')::numeric) then raise exception 'O custo de Mana deve ser inteiro e não negativo.';end if;
     end loop;
    elsif entry->>'attribute' is null or entry->>'attribute' not in('for','agi') then raise exception 'A técnica usa Força ou Agilidade.';end if;
   end if;
  end loop;
 end loop;
end $$;
revoke all on function private.arkanis48_validate(jsonb) from public,anon,authenticated;

create or replace function private.arkanis48_character_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare r public.campaign_rules;
begin
 if (select slug from public.rpg_systems where id=new.rpg_system_id)<>'arkanis' then return new;end if;
 perform private.arkanis48_validate(new.system_data);
 select * into r from public.campaign_rules where campaign_id=new.campaign_id;
 if r.lock_player_level and (new.system_data->>'level')::integer<>r.party_level then raise exception 'O nível do grupo é definido pelo mestre.';end if;
 if tg_op='UPDATE' then new.updated_at=greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');end if;
 return new;
end $$;
revoke all on function private.arkanis48_character_guard() from public,anon,authenticated;
drop trigger if exists zz_arkanis48_character on public.characters;
create trigger zz_arkanis48_character before insert or update on public.characters for each row execute function private.arkanis48_character_guard();

-- Existing D&D validators remain unchanged for D&D and do not interpret another system.
do $guards48$
declare signature text;definition text;guard text;
begin
 foreach signature in array array['private.dnd37_validate_sheet(uuid)','private.dnd37_training_permissions()','private.sheet41_inspiration()'] loop
  definition=pg_get_functiondef(to_regprocedure(signature));
  if definition is null then raise exception 'Migração anterior ausente: %',signature;end if;
  if strpos(definition,'-- arkanis48 boundary')=0 then
   guard=case when signature='private.dnd37_validate_sheet(uuid)' then E'begin\n -- arkanis48 boundary\n if exists(select 1 from public.characters c join public.rpg_systems r on r.id=c.rpg_system_id where c.id=p_character and r.slug=\'arkanis\') then return;end if;'
    else E'begin\n -- arkanis48 boundary\n if (select slug from public.rpg_systems where id=new.rpg_system_id)=\'arkanis\' then return new;end if;' end;
   execute regexp_replace(definition,'\mbegin\M',guard,'i');
  end if;
 end loop;
 definition=pg_get_functiondef('private.campaign_custom_item_guard()'::regprocedure);
 if strpos(definition,'-- arkanis48 catalog')=0 then
  execute regexp_replace(definition,'\mbegin\M',E'begin\n -- arkanis48 catalog\n if exists(select 1 from public.characters ch join public.rpg_systems rs on rs.id=ch.rpg_system_id join public.arkanis_ingredients ai on ai.id=new.data->>\'ingredient_id\' where ch.id=new.character_id and rs.slug=\'arkanis\' and ai.name=new.data->>\'name\') then return new;end if;','i');
 end if;
end $guards48$;

create or replace function private.arkanis48_inventory_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.characters c join public.rpg_systems r on r.id=c.rpg_system_id where c.id=new.character_id and r.slug='arkanis') then return new;end if;
 if coalesce(length(trim(new.data->>'name')),0) not between 1 and 120 or jsonb_typeof(new.data->'quantity') is distinct from 'number' or (new.data->>'quantity')::numeric<>trunc((new.data->>'quantity')::numeric) or (new.data->>'quantity')::integer not between 0 and 9999 or coalesce((new.data->>'weight')::numeric,-1)<0 then raise exception 'Confira nome, quantidade e peso do item.';end if;
 if new.data ? 'ingredient_id' and not exists(select 1 from public.arkanis_ingredients where id=new.data->>'ingredient_id' and name=new.data->>'name') then raise exception 'Ingrediente não encontrado no catálogo de Arkanis.';end if;
 if new.data ? 'tags' and jsonb_typeof(new.data->'tags') is distinct from 'array' then raise exception 'Tags de item inválidas.';end if;
 return new;
end $$;
revoke all on function private.arkanis48_inventory_guard() from public,anon,authenticated;
drop trigger if exists zz_arkanis48_inventory on public.character_inventory;
create trigger zz_arkanis48_inventory before insert or update on public.character_inventory for each row execute function private.arkanis48_inventory_guard();

create or replace function public.save_arkanis_character(p_payload jsonb,p_expected_updated_at timestamptz default null) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare cid uuid=(p_payload->>'id')::uuid;s jsonb=p_payload->'sheet';prior public.characters;saved public.characters;entry jsonb;ids uuid[]='{}';
begin
 if auth.uid() is null then raise exception 'Entre na sua conta.' using errcode='42501';end if;
 if not exists(select 1 from public.rpg_systems r join public.campaigns c on c.rpg_system_id=r.id where c.id=(p_payload->>'campaign_id')::uuid and r.id=(p_payload->>'rpg_system_id')::uuid and r.slug='arkanis') then raise exception 'Escolha uma campanha de Arkanis acessível.' using errcode='42501';end if;
 select * into prior from public.characters where id=cid for update;
 if prior.id is not null and (prior.campaign_id<>(p_payload->>'campaign_id')::uuid or prior.owner_id<>(p_payload->>'owner_id')::uuid or prior.rpg_system_id<>(p_payload->>'rpg_system_id')::uuid) then raise exception 'O vínculo da ficha não pode ser alterado.' using errcode='42501';end if;
 if prior.id is null and p_expected_updated_at is not null or prior.id is not null and prior.updated_at is distinct from p_expected_updated_at then raise exception 'Esta ficha foi atualizada ou removida. Reabra antes de salvar; seu rascunho foi preservado.' using errcode='40001';end if;
 if jsonb_typeof(s->'inventory') is distinct from 'array' or jsonb_array_length(s->'inventory')>1000 then raise exception 'Inventário inválido (até 1.000 registros).';end if;
 insert into public.characters(id,campaign_id,rpg_system_id,owner_id,name,portrait_path,appearance,biography,system_data)
 values(cid,(p_payload->>'campaign_id')::uuid,(p_payload->>'rpg_system_id')::uuid,(p_payload->>'owner_id')::uuid,trim(p_payload->>'name'),p_payload->>'portrait_path',coalesce(p_payload->>'appearance',''),coalesce(p_payload->>'biography',''),s-'inventory')
 on conflict(id) do update set name=excluded.name,portrait_path=excluded.portrait_path,appearance=excluded.appearance,biography=excluded.biography,system_data=excluded.system_data returning * into saved;
 for entry in select value from jsonb_array_elements(s->'inventory') loop
  if (entry->>'id')::uuid=any(ids) then raise exception 'Um item não pode aparecer duas vezes no inventário.';end if;
  ids=array_append(ids,(entry->>'id')::uuid);
  insert into public.character_inventory(id,character_id,data) values((entry->>'id')::uuid,cid,entry-'id')
   on conflict(id) do update set data=excluded.data where public.character_inventory.character_id=cid;
 end loop;
 delete from public.character_inventory where character_id=cid and id<>all(ids);
 return jsonb_build_object('id',saved.id,'updated_at',saved.updated_at);
end $$;
revoke all on function public.save_arkanis_character(jsonb,timestamptz) from public,anon;
grant execute on function public.save_arkanis_character(jsonb,timestamptz) to authenticated;

-- Keep the administrative compatibility check aligned with this installed upgrade.
do $item_metadata48$
declare definition text;
begin
 definition=pg_get_functiondef('private.validate_campaign_item(jsonb)'::regprocedure);
 if strpos(definition,'''ingredient_id''')=0 then
  execute replace(definition,'''passive_requires_equipped'',''image_path''','''passive_requires_equipped'',''image_path'',''ingredient_id''');
 end if;
 definition=pg_get_functiondef('public.save_campaign_item(jsonb,integer)'::regprocedure);
 if strpos(definition,'-- arkanis48 item icon')=0 then
  definition=replace(definition,'d=private.validate_campaign_item(p_payload->''data'');',$item_guard48$
  d=private.validate_campaign_item(p_payload->'data');
  -- arkanis48 item icon
  if d ? 'ingredient_id' and not exists(select 1 from public.arkanis_ingredients where id=d->>'ingredient_id' and name=d->>'name') then raise exception 'Ingrediente não encontrado no catálogo de Arkanis.';end if;
  $item_guard48$);
  definition=replace(definition,'d->>''image_path'' not like ''/images/%''',$icon_guard48$
   d->>'image_path' not like '/images/%' and not exists(
    select 1 from public.campaigns c join public.rpg_systems r on r.id=c.rpg_system_id
    join public.arkanis_ingredients a on a.id=d->>'ingredient_id'
    where c.id=cid and r.slug='arkanis' and a.name=d->>'name' and a.icon=d->>'image_path'
   )
  $icon_guard48$);
  execute definition;
 end if;
end $item_metadata48$;

