do $item_references48$
declare definition text;
begin
 definition=pg_get_functiondef('private.media_is_referenced47(text,text)'::regprocedure);
 if strpos(definition,'-- arkanis48 item references')=0 then
  execute regexp_replace(definition,'\mbegin\M',$reference_guard48$begin
   -- arkanis48 item references
   if p_bucket='campaign-media' and (
    exists(select 1 from public.campaign_items where data->>'image_path'=p_name)
    or exists(select 1 from public.character_inventory where data->>'image_path'=p_name)
    or exists(select 1 from private.campaign_item_versions where data->>'image_path'=p_name)
   ) then return true;end if;
  $reference_guard48$,'i');
 end if;
end $item_references48$;
create or replace function private.item_media_reference48() returns trigger language plpgsql security definer set search_path='' as $$
declare previous_path text;next_path text;job private.media_cleanup_jobs;
begin
 if tg_op<>'INSERT' then previous_path=old.data->>'image_path';end if;
 if tg_op<>'DELETE' then next_path=new.data->>'image_path';end if;
 if next_path is distinct from previous_path and next_path is not null then
  select * into job from private.media_cleanup_jobs where bucket_id='campaign-media' and name=next_path for update;
  if found and job.lease_until>clock_timestamp() then raise exception 'A imagem está sendo atualizada. Escolha a imagem novamente.' using errcode='40001';end if;
  if found then delete from private.media_cleanup_jobs where id=job.id;end if;
 end if;
 if previous_path is distinct from next_path then perform private.queue_media_cleanup47('campaign-media',previous_path);end if;
 return case when tg_op='DELETE' then old else new end;
end $$;
revoke all on function private.item_media_reference48() from public,anon,authenticated;
drop trigger if exists zz_item_media48 on public.campaign_items;
create trigger zz_item_media48 before insert or update or delete on public.campaign_items for each row execute function private.item_media_reference48();
