create trigger zz_item_media48 before insert or update or delete on public.character_inventory for each row execute function private.item_media_reference48();
drop trigger if exists zz_item_media48 on private.campaign_item_versions;
create trigger zz_item_media48 before insert or update or delete on private.campaign_item_versions for each row execute function private.item_media_reference48();

